<?php

namespace App\Libraries;

/**
 * Starting knowledge of the NEXUS-L help bot: what each page does, how to do every common task, and how to fix the
 * problems users run into. `php spark brain:seed` loads it (safe to repeat: entries are matched by title).
 * Everything here describes THIS system only. New knowledge is added from the Brain console (Teach / Import) and from
 * answers administrators give in escalated chats.
 */
class BrainSeed
{
    /** @return list<array<string,mixed>> */
    public static function all(): array
    {
        $o = static fn (string $label, string $url, bool $admin = false): array => ['type' => 'open', 'label' => $label, 'url' => $url] + ($admin ? ['role' => 'admin'] : []);
        $k = static fn (string $title, string $keywords, string $body, array $steps = [], array $extra = []): array => array_merge(['title' => $title, 'keywords' => $keywords, 'body' => $body, 'steps' => $steps], $extra);

        return [
            // ------------------------------------------------------------------ general
            $k('What is NEXUS-L and what can I do here?', 'what is nexus-l, about, overview, what can i do, purpose, features, system', 'NEXUS-L is the laboratory workspace of the QC lab. You use it to record material and shoe-bonding test results, produce the official test reports (print or PDF), calculate averages and pass/fail ratings, send lab results to InterLink 2.0, and chat with colleagues in the Inbox.', ['Dashboard: your sign-in activity and security summary.', 'QC Lab Reports: Lab Tracker, Material Tests, Shoe Bonding (U60), Calculators & Standards.', 'InterLink Sync: send lab results to InterLink and keep them in step.', 'Inbox: messages with colleagues.', 'Help: guides and common questions.'], ['actions' => [$o('Open Help', 'help')]]),
            $k('How do I sign in?', 'sign in, login, log in, username, password, enter system, access', 'Open the NEXUS-L address in Chrome or Edge, type your username (or email) and password and press Sign in. Tick "Remember me" on your own computer to stay signed in.', ['Type your username or email.', 'Type your password (use the eye icon to check it).', 'Press Sign in.', 'If it fails, check Caps Lock and try again; if it still fails, ask an administrator.'], ['page_match' => 'login']),
            $k('I forgot my password', 'forgot password, reset password, cannot remember password, change password, lost password', 'Use "Forgot password?" on the sign-in page. A verification code is sent to your registered contact; enter it and choose a new password.', ['On the sign-in page press "Forgot password?".', 'Enter your username or email and request the code.', 'Enter the code you received.', 'Choose a new password and sign in.', 'If no code arrives, ask an administrator to reset it.'], ['page_match' => 'login']),
            $k('How do I create an account?', 'register, create account, sign up, new user, join, registration', 'Press "Create one" on the sign-in page and fill in your details. By registering you accept the Terms and Privacy notice (including that your activity in the system is recorded to improve help and support). If you cannot sign in after registering, ask an administrator.', ['Press "Create one" under the sign-in button.', 'Fill in your details and accept the Terms and Privacy notice.', 'If you cannot sign in afterwards, ask an administrator.'], ['page_match' => 'register']),
            $k('I was signed out by itself (session expired)', 'why did the system log me out, kicked out of the system, logged me out, keeps logging me out, logs me out, signed out, logged out, session expired, timeout, idle, automatically logout, please sign in to continue, 401, unauthorized', 'For security NEXUS-L signs you out after 30 minutes without activity. Your saved work is not lost; unsaved changes on the screen are. Sign in again and continue. Save often, especially before a break.', ['Sign in again with the same account.', 'Reopen the report you were working on from the Lab Tracker.', 'If you were typing, check that your last changes were saved.'], ['error_match' => '401']),
            $k('"You are not authorized to access that page"', 'not authorized, no permission, access denied, forbidden, 403, admin only, cannot open page, permission', 'That page is only for administrators (for example the Report Designer and the Brain console). Regular users do not see those pages. If you need a change that only an admin can make, send the question to an administrator from this chat.', ['Check that you are signed in with the right account (your role shows under your name at the top right).', 'Ask an administrator for the change, or press "Talk to an administrator" below.'], ['error_match' => '403']),
            $k('How do I collapse the sidebar to get more space?', 'sidebar, collapse, menu, hide menu, more space, bigger screen, icon bar, narrow menu', 'On large screens press the menu button (three lines) at the top left. The sidebar shrinks to an icon strip and the page uses the extra width. Press it again to expand. NEXUS-L remembers your choice.', ['Press the three-line button at the top left of the page.', 'Hover an icon to see its name.', 'Press the button again to bring the full menu back.']),
            $k('Can I use NEXUS-L on a phone or tablet?', 'phone, mobile, tablet, small screen, responsive, ipad, android', 'Yes. On small screens the menu slides in from the left (three-line button) and the pages rearrange to fit. Large tables scroll sideways. For long data entry a computer is more comfortable.'),
            $k('How do I sign out?', 'sign out, log out, logout, leave, exit', 'Press "Sign out" at the bottom of the sidebar. Always sign out on shared computers.', ['Open the sidebar if it is hidden (three-line button).', 'Press Sign out at the bottom.']),
            $k('What do the Dashboard cards mean?', 'dashboard, cards, sign-in health, security summary, activity, session started, idle timeout, home page', 'The Dashboard shows who you are signed in as, your role, when the session started and the idle timeout, your sign-in health (successful versus failed sign-ins in the last 7 days), and your recent activity. It is a personal security summary.', [], ['page_match' => 'dashboard', 'actions' => [$o('Open Dashboard', 'dashboard')]]),
            $k('Which browser should I use?', 'browser, chrome, edge, firefox, safari, internet explorer, supported browser, compatibility', 'Use the current Google Chrome or Microsoft Edge. Internet Explorer is not supported. If something looks wrong after an update, hold Ctrl and press F5 to reload the page completely.'),
            $k('The page looks old or something is missing after an update', 'hard refresh, ctrl f5, cache, old version, update not showing, refresh, clear cache, reload', 'Your browser may be showing an older copy. Press Ctrl + F5 (hold Ctrl, press F5) to reload the page completely.', ['Press Ctrl + F5.', 'If it still looks old, close the tab and open NEXUS-L again.']),

            // ------------------------------------------------------------------ lab reports
            $k('How do I find a lab report?', 'find report, search, lab ref, labrefno, tr no, look up, locate, tracker, search record', 'Open QC Lab Reports > Lab Tracker. Type a Lab Ref No, TR No, material code, style, supplier or MTL number in the search box and press Search, or press a category button to filter by report type.', ['Open Lab Tracker.', 'Type part of the Lab Ref No (for example DTP20261012) and press Search.', 'Press Open Form on the row to open the report.'], ['page_match' => 'dtr', 'actions' => [$o('Open Lab Tracker', 'dtr?tab=tracker')]]),
            $k('How do I open and edit an existing report?', 'open report, edit report, open form, view report, change report, existing record', 'In the Lab Tracker press "Open Form" on the report. The right form opens with all saved readings. Change what you need and press "Save Report to NEXUS-L".', ['Lab Tracker > find the report > Open Form.', 'Edit the values.', 'Press Save Report to NEXUS-L. Saving always needs your own click.'], ['page_match' => 'dtr']),
            $k('How do I create a new material test report?', 'new report, new record, create report, add report, start report, material test form, new lab ref', 'Open QC Lab Reports > Material Tests, choose the form (fabric, leather, labels, rubber and so on), press "+ New Record", enter the Lab Reference No., fill the sample details, load the machine results, then Save.', ['Material Tests > choose the form in "1. Select Material Test Form".', 'Press + New Record.', 'Type the Lab Reference No. (and the TR No.).', 'Use Auto-Lookup to fill material, PO and DSR details.', 'Press Load Machine Results to bring in the readings.', 'Check the ratings and press Save Report to NEXUS-L.'], ['page_match' => 'dtr', 'actions' => [$o('Open Material Tests', 'dtr?tab=material')]]),
            $k('Which material forms are available?', 'material forms, types, fabric, leather, webbing, foxing tape, hardware, label, sockliner, foam, rubber, carton box, insole, report types', 'There are 10 material forms: Fabric (FBU/FBL), Webbing / Shoelace / Thread, Hardware, Foxing Tape & Heel Logo, Leather (LEU/LEL), Woven / Size / Transfer Label, Sockliner & Foam, Rubber Outsole, Carton Box and Insole Board. Whole Shoe Bonding (U60) has its own tab.', [], ['page_match' => 'dtr']),
            $k('How do I load the machine results into a report?', 'load machine results, machine file, excel, xlsx, csv, readings, test machine, import readings, load results, u60 file, outdata', 'Enter the Lab Reference No. and press "Load Machine Results" (or "Load U60 Machine File" for bonding). NEXUS-L finds the machine file with that Lab Ref No., reads the values from it and fills the readings. The machine file itself is never changed.', ['Make sure the Lab Reference No. is typed exactly as on the sample.', 'Press Load Machine Results.', 'Check the message: it says how many readings were loaded and from which file.', 'Review the values and press Save Report to NEXUS-L.'], ['page_match' => 'dtr', 'diagnose' => 'machine_share', 'actions' => [$o('Open Material Tests', 'dtr?tab=material'), $o('Open Shoe Bonding', 'dtr?tab=bonding')]]),
            $k('"No matching machine output file found"', 'cant find the machine file, machine file missing, where is the machine file, machine file not there, cannot find excel file, no matching machine output file, machine file not found, file not found, load machine results fails, no readings loaded, no file, cannot load machine, missing file, nothing loaded', 'The machine file for that Lab Ref No. was not found. Usual causes: the test has not finished or the machine has not saved the file yet; the Lab Ref No. is typed differently (check the letters after the date and the -L / -R suffix); or the machine-file location is not reachable.', ['Check the Lab Ref No. letter by letter (for example DTP20261012FAA8-L).', 'Wait a minute after the test ends and try again.', 'Ask the person at the machine whether the file was saved.', 'If the diagnosis below says the location is not reachable, tell an administrator.'], ['page_match' => 'dtr', 'error_match' => 'machine', 'diagnose' => 'machine_share']),
            $k('The loaded machine values look wrong', 'wrong values, values wrong, incorrect readings, readings wrong, different values, machine values wrong, strange numbers, not matching', 'First press "Refresh & Apply Smart Standards" so averages and pass/fail are recalculated. Then check that the Lab Ref No. is the right one (a retest has its own file) and that the report is the right side (-L left or -R right). If the numbers still differ from the machine file, an administrator can check the reading rules in the Report Designer (Excel readers).', ['Press Refresh & Apply Smart Standards.', 'Check the Lab Ref No. and the side (-L / -R).', 'Compare one reading with the machine file.', 'If it still differs, press "Talk to an administrator".'], ['page_match' => 'dtr']),
            $k('How do I save a report?', 'save report, save, store, keep, saving, submit report, save changes', 'Press "Save Report to NEXUS-L" (material) or "Save Bonding Report" (shoe bonding). Saving is always done by you; nothing is saved automatically. After saving, the report appears in the Lab Tracker and is available to InterLink Sync.', ['Check the Lab Ref No. and the ratings.', 'Press Save Report.', 'Wait for the green confirmation message.'], ['page_match' => 'dtr']),
            $k('Data is not saving', 'not saving, cannot save, save failed, changes lost, save error, save does nothing, data not saved, record not saved', 'If saving does nothing or shows an error: (1) check the confirmation message at the top, (2) make sure the Lab Reference No. is filled, (3) check you were not signed out (reload the page and see if the sign-in page appears), and (4) try once more. If it keeps failing, copy the exact message and send the question to an administrator.', ['Fill the Lab Reference No. (marked *).', 'Reload the page: if you are asked to sign in, sign in and repeat.', 'Press Save again and read the message.', 'Press "Talk to an administrator" with the message text.'], ['page_match' => 'dtr']),
            $k('How do I print or preview a material report?', 'print material report, preview report, print preview, official sheet, print test report, print', 'Open the report and press "Print / Preview Report". A preview of the official sheet opens with the VF and SATRA logos. From there press "Print Report / Save as PDF" or "Download PDF". The sheet is scaled to fit one A4 page.', ['Open the report (Lab Tracker > Open Form).', 'Press Print / Preview Report.', 'Check the sheet, then press Download PDF or Print Report / Save as PDF.'], ['page_match' => 'dtr']),
            $k('What is the difference between Download PDF, Print Report / Save as PDF and Official PDF?', 'download pdf, official pdf, save as pdf, difference pdf, which pdf, pdf options, three buttons', 'Download PDF creates a PDF of the sheet shown on screen (with both logos, one A4 page) on the server. Print Report / Save as PDF uses your browser: choose your printer or "Save as PDF". Download Official PDF produces the PDF from the original Access report layout and only works where Microsoft Access is available on the server.', [], ['page_match' => 'dtr', 'diagnose' => 'pdf_engine']),
            $k('The PDF is blank or Download PDF fails', 'download pdf button not working, pdf button does nothing, cannot download pdf, pdf wont download, print preview not working, pdf blank, pdf empty, download pdf not working, pdf failed, pdf error, white pdf, pdf not created, print blank, blank page print', 'Reload the page with Ctrl + F5 and open the preview again. "Download PDF" needs Chrome or Edge installed on the server; if the diagnosis below says it is missing, use "Print Report / Save as PDF" and tell an administrator. A blank browser print is fixed by the latest update: reload the page first.', ['Press Ctrl + F5.', 'Open the report preview again.', 'Try Download PDF; if it fails, use Print Report / Save as PDF.', 'Tell an administrator if the diagnosis shows the PDF engine is missing.'], ['page_match' => 'dtr', 'error_match' => 'pdf', 'diagnose' => 'pdf_engine']),
            $k('The report does not fit on one page', 'one page, a4, two pages, fit page, page size, report too long, spills second page, paper size, scale', 'The preview and PDF scale the whole sheet to fit one A4 page automatically (6 mm margins). If your printer dialog adds its own scaling, set the paper size to A4 and the scale to 100 %.', ['In the print dialog choose paper size A4.', 'Set scale to 100 % (not "fit" or custom).', 'Turn off "Headers and footers" for a clean sheet.']),
            $k('Where are the VF and SATRA logos on the report?', 'logo, vf logo, satra logo, accreditation, logos on report, header logo', 'The VF logo is at the top left and the SATRA "Accredited Laboratory No. 08A03" mark at the top right of the report header, on the same line as the test title. They appear in the preview, the printout and Download PDF.'),
            $k('What does PASS, TOLERABLE and FAIL mean?', 'pass, fail, tolerable, rating, result, stamp, overall result, meaning, status, red yellow green', 'PASS (green) meets the standard. TOLERABLE (amber) is inside the tolerance band below the standard. FAIL (red) is below tolerance and needs a retest or action. The overall stamp shows the worst result of all tests in the report.', [], ['page_match' => 'dtr']),
            $k('How are bonding results rated?', 'bonding rating, bonding standard, adult 3, children 2.5, tolerable bonding, fito 1.0, spot rating, std, utf fto fito pass', 'For Adult styles the standard is 3.0 kg/cm: 3.0 or more is PASS, 2.4 to 2.99 is TOLERABLE, below 2.4 is FAIL. For Children the standard is 2.5: 2.5 or more PASS, 2.0 to 2.49 TOLERABLE, below 2.0 FAIL. The filler (FiTO) standard is 1.0: 1.0 or more PASS, 0.8 to 0.99 TOLERABLE, below 0.8 FAIL. The report result is the worst of the three groups.', [], ['page_match' => 'dtr']),
            $k('What do UTF, FTO and FiTO mean?', 'utf, fto, fito, upper to foxing, foxing to outsole, filler to outsole, bonding parts, spots meaning', 'UTF = Upper to Foxing, FTO = Foxing to Outsole, FiTO = Filler to Outsole (center). Each is a group of measuring spots read by the U60 machine in kg/cm. FiTO has up to 13 spots, UTF and FTO up to 45.', [], ['page_match' => 'dtr']),
            $k('How do I create a whole shoe bonding report?', 'create bonding report, new bonding, shoe bonding, u60, load u60 file, bonding test, new bonding report', 'Open QC Lab Reports > Shoe Bonding (U60), press "+ New Bonding Report", type the Lab Reference No. (ending -L for left or -R for right), press "Load U60 Machine File" and review the values, then press "Save Bonding Report". Technician, side, age category, standard and the pass/fail result are filled automatically.', ['Shoe Bonding (U60) > + New Bonding Report.', 'Type the Lab Reference No. (for example DTP20261012FAA8-L).', 'Press Load U60 Machine File.', 'Check the spots, age category and result.', 'Press Save Bonding Report.'], ['page_match' => 'dtr', 'diagnose' => 'machine_share', 'actions' => [$o('Open Shoe Bonding', 'dtr?tab=bonding')]]),
            $k('How many spots does a shoe have (spot rules)?', 'spots, spot count, toddler 14, kids 16, children 24, adult 35, how many points, number of points, age category', 'The number of spots follows the age category: Toddler 14, Kids 16, Children 24, Adult up to 35 (the machine file decides how many are filled). The matching shoe diagram (26 to 34 points) is chosen from the highest spot that has a value.', [], ['page_match' => 'dtr']),
            $k('How do I view the left and right bonding report?', 'bonding report preview, left right report, preview bonding, print bonding, bonding sheet, left shoe right shoe', 'In Shoe Bonding (U60) open the report and press "Print / Preview Bonding Report". The sheet shows the test results, the shoe diagram with every value at its point, and the left / right center values. Use Download PDF or Print Report / Save as PDF from the preview.', [], ['page_match' => 'dtr', 'actions' => [$o('Open Shoe Bonding', 'dtr?tab=bonding')]]),
            $k('The points or values are not on the shoe in the bonding report', 'points not shown, values not on shoe, shoe diagram empty, dots missing, no points, spots missing on report, points wrong place, misplaced values', 'The values are placed at fixed positions over the shoe picture. If they are missing or misplaced, an administrator can fix the positions in Report Designer > Shoe diagram (drag each value box and dot to its spot, then Save layout). Check also that the report really has spot values loaded.', ['Confirm the spot table in the report has values.', 'Hard refresh with Ctrl + F5 and open the preview again.', 'Ask an administrator to adjust the layout in the Report Designer.'], ['page_match' => 'dtr', 'actions' => [$o('Open Report Designer (admin)', 'designer?tab=diagram', true)]]),
            $k('Download Official Access PDF says Not Found or fails', 'official pdf, access pdf, not found pdf, bonding access pdf, 404 pdf, official access report', 'The official PDF is produced by Microsoft Access on the server from the original bonding report. It fails when Access is not available, the report does not exist in the Access file (reports created only in NEXUS-L), or the server could not open the Access file. Use "Download PDF" instead: it makes the same sheet from NEXUS-L with both logos.', ['Use Download PDF in the preview instead.', 'If you need the Access layout, tell an administrator.'], ['page_match' => 'dtr', 'error_match' => 'bonding-access-pdf', 'diagnose' => 'pdf_engine']),
            $k('What does "Auto-Lookup Material / PO / DSR" do?', 'auto lookup, lookup, material code, po lot, dsr, mtl, fill details automatically, master data', 'It fills the sample details from the master lists: type a Material Code (or the production code / MTL number) and press Tab, or press the Auto-Lookup button, and the description, supplier, style, colour and DSR details are filled in for you.', [], ['page_match' => 'dtr']),
            $k('How do the automatic calculations work?', 'automatic calculation, average, min max, thickness, hardness, weight, specific gravity, auto compute, rating calculation, refresh apply smart standards', 'Readings are averaged automatically (for example thickness 1 to 6 gives Min, Max and Average). "Refresh & Apply Smart Standards" looks up the standard for the material type and thickness and recalculates every rating. Rating fields are filled by the system; change them only if the procedure allows it.', ['Enter or load the readings.', 'Press Refresh & Apply Smart Standards.', 'Read the ratings and the overall stamp.'], ['page_match' => 'dtr']),
            $k('What are the calculators for?', 'calculator, calculators, weight calculator, shrinkage, specific gravity, compression set, din abrasion, ross flex, calc tab', 'The Calculators & Standards tab has calculators for Weight (fabric / leather / insole), Specific Gravity, Compression Set, DIN Abrasion, Ross Flex and Shrinkage. Enter the raw values, read the result, and press "Apply to Material Form" to copy it into the open report. The Standards lookup explorer lets you search standards and the DSR / shoe / material lists.', [], ['page_match' => 'dtr', 'actions' => [$o('Open Calculators', 'dtr?tab=calculators')]]),
            $k('How do I look up a standard or a DSR / material / shoe record?', 'standards lookup, dsr lookup, master lookup explorer, find standard, material list, shoe list, lookup explorer, search standards', 'Open Calculators & Standards and use the Live Master Lookup Explorer: type a code, style, MTL number or material type and the matching standards and records are listed.', [], ['page_match' => 'dtr']),
            $k('I cannot find a Lab Ref No. in the system', 'cannot find lab ref, lab ref missing, not in tracker, record not found, no result search, missing report, lab reference not found', 'Check the spelling (the date part and the letters after it), try only the first part, and clear the category filter. If the report was never saved in NEXUS-L it will not be listed: create it with "+ New Record" and load the machine results. If it should exist, tell an administrator.', ['Search with only part of the number.', 'Press "All Reports" to clear the category filter.', 'If it was never saved, create it as a new record.'], ['page_match' => 'dtr']),
            $k('What is the Stamp Reviewed button?', 'stamp reviewed, reviewed by, review stamp, approve report, reviewer', 'Stamp Reviewed records that a reviewer has checked the report (reviewer name and date). Use it only after you have checked the values.', [], ['page_match' => 'dtr']),

            // ------------------------------------------------------------------ designer (admin)
            $k('How do I open the Report Designer?', 'report designer, open designer, designer, customize report, edit layout, admin tools', 'The Report Designer is for administrators. Open it from the sidebar ("Report Designer") or from the admin card in Calculators & Standards. It has four tabs: Shoe diagram, Form fields, Excel readers and File locations.', [], ['role_min' => 'admin', 'page_match' => 'designer', 'actions' => [$o('Open Report Designer', 'designer', true)]]),
            $k('How do I move the points and dots on the shoe diagram?', 'move points, drag points, shoe diagram, dots, movable dots, place points, adjust points, arrange values, resize box', 'In Report Designer > Shoe diagram choose the number of points (and a record to preview real values). Drag a value box to move it; drag the small square in its corner to resize; arrow keys nudge it (Shift = bigger steps). Tick "Movable dots & lines" to draw the dots and leader lines yourself and drag every dot onto its exact spot on the shoe. Press Save layout to apply it to everyone.', ['Pick the point count (for example 27 points).', 'Optionally pick a preview record.', 'Drag value boxes and dots to their spots.', 'Press Save layout.'], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I add a START marker or extra items to the report?', 'start marker, start point, add text, add chart, add image, add line, extra items, starting point', 'Use the buttons above the diagram: "+ Start point" (a red diamond you drag to where the test starts), "+ Text", "+ Value from record", "+ Bar chart", "+ Image" and "+ Line". Select an item to edit its label, size and colour in the side panel.', [], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I hide, rename or reorder form fields?', 'hide field, rename field, reorder fields, custom field, add field, form fields, hide input, field order', 'In Report Designer > Form fields untick a field to hide it from users, rename its label, and use the arrows to change the order. "Custom fields" adds extra text boxes to the bonding form. Press Save form fields.', [], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I change which Excel cells are read (Excel readers)?', 'excel readers, reading rules, cells, columns changed, excel layout changed, machine layout, reader, sheet, rows changed, map excel', 'In Report Designer > Excel readers pick the report type. Each reader names the machine folder and sheet and lists rules (a fixed cell, a column of values, rows labelled M1 M2, a label with a value next to it). Use "Preview file" to see the real file, click a cell to fill the active rule, then "Test" to see exactly what would be loaded, and "Save readers".', ['Pick the report type and press Preview file (type a Lab Ref No. above).', 'Click the cell or column in the grid to fill the active rule.', 'Press Test and check the loaded values.', 'Press Save readers.'], ['role_min' => 'admin', 'page_match' => 'designer']),
            $k('How do I move the machine files to another PC or share?', 'file location, move files, change share, new location, outdata, machine files location, change path, transfer files, new server', 'In Report Designer > File locations enter the new root folder (for example \\\\server\\share\\OUTDATA), press "Test location" (it lists every report folder and how many files were found) and then "Save location". No code change is needed.', ['Open Report Designer > File locations.', 'Type the new location.', 'Press Test location and confirm the folders are found.', 'Press Save location.'], ['role_min' => 'admin', 'page_match' => 'designer', 'diagnose' => 'machine_share']),
            $k('My Designer layout did not save or reset', 'layout not saved, designer reset, designer not saving, layout lost, save layout, reset to default', 'Press "Save layout" after changing the diagram; the message "Saved" with the time confirms it. "Reset to default" removes your saved layout for that point count. Users see the new layout the next time they open the report (Ctrl + F5 if the old one still shows).', [], ['role_min' => 'admin', 'page_match' => 'designer']),

            // ------------------------------------------------------------------ interlink
            $k('What is InterLink Sync?', 'interlink, interlink 2.0, intertek, vf portal, sync, what is interlink, send results, portal', 'InterLink Sync connects NEXUS-L to the InterLink 2.0 portal. You pick a Lab Reference, check the data that will fill the InterLink form, and sync it. The Sync Center keeps the connection and the queue running in the background even when the page is closed.', [], ['page_match' => 'interlink', 'actions' => [$o('Open InterLink Sync', 'interlink')]]),
            $k('How do I sign in to InterLink in the Sync Center?', 'sign in interlink, connect interlink, interlink login, connect session, sync center sign in, interlink not connected', 'Press "Sign in to InterLink" in the Sync Center. A Chrome window opens on the server PC: sign in to InterLink there as usual. When the InterLink list appears the window closes by itself and the status turns green ("Connected"). You never type the InterLink password into NEXUS-L.', ['Press Sign in to InterLink.', 'Sign in in the window that opens.', 'Wait for the status to show Connected.', 'If no window opens, ask whoever is at the server PC to double-click tools\\Connect-InterLink.bat.'], ['page_match' => 'interlink', 'diagnose' => 'interlink_session']),
            $k('InterLink says the session ended', 'session ended, interlink session expired, sign in again interlink, relogin, expired interlink, red banner, reconnect', 'InterLink signs people out after a while. Press "Sign in to InterLink" in the Sync Center and sign in again. Everything you queued is kept and continues automatically once connected.', ['Press Sign in to InterLink.', 'Sign in in the window that opens.', 'The status turns green and the queue continues.'], ['page_match' => 'interlink', 'error_match' => 'interlink', 'diagnose' => 'interlink_session']),
            $k('How do I choose which Lab References to sync?', 'choose lab reference, pick lab ref, select lab ref, queue selected, sync selected, which lab ref sync, sync lab reference', 'In the Sync Center type the InterLink Application No., search and tick the Lab References you want (you can tick many), then press "Queue selected". The worker processes them one by one.', ['Type the Application No.', 'Search and tick the Lab References.', 'Press Queue selected.', 'Watch the Queue box for the status.'], ['page_match' => 'interlink']),
            $k('What does "prepared" mean in the queue?', 'prepared, queue status, pending, failed, queue, queued item, status prepared, waiting', 'Waiting = not processed yet. Prepared = the data for the InterLink form has been built and logged. Failed = something went wrong (hover the status to read why; it is retried up to 3 times). Note: writing the data into InterLink itself is still a manual step done in the portal form.', [], ['page_match' => 'interlink']),
            $k('Why does it take several seconds to open the U or E form?', 'slow interlink, u form slow, e form slow, loading interlink, upload form slow, application form slow, takes long, waiting', 'NEXUS-L reads the live form from InterLink, which can take 5 to 6 seconds. A loading panel is shown while it works; the form fills in as soon as InterLink answers. If it takes much longer, check that the Sync Center shows Connected.', [], ['page_match' => 'interlink', 'diagnose' => 'interlink_session']),
            $k('How do I use the Pre-Sync dialog?', 'pre-sync dialog, sync dialog, confirm and fill form, one click send, fields to sync, select lab reference dialog, sync form', 'Open the InterLink form (U) and press the Sync button. Choose the Lab Reference, tick the fields you want to fill, edit the values if needed, then "Confirm & Fill Form" (fills the form in NEXUS-L) or "Confirm, Fill & 1-Click Send Report". Review before you confirm: sending is your decision.', [], ['page_match' => 'interlink']),
            $k('What are Live changes and tracked columns in the Sync Center?', 'live changes, tracked columns, interlink changes, other users changed, new column, feed, realtime', 'The background worker reads InterLink about once a minute. "Live changes" lists rows that someone else changed or added and any new InterLink column; "columns tracked" is how many InterLink columns NEXUS-L knows. So updates made by other users show up within about a minute.', [], ['page_match' => 'interlink']),
            $k('The background worker is not running', 'worker not running, background worker, scheduled task, status out of date, not checked, task scheduler, worker stopped', 'The Sync Center warns when the worker has not checked InterLink for 5 minutes. An administrator starts it once by running tools\\interlink-worker.ps1 from an elevated PowerShell; it then runs every minute by itself.', ['Administrator: open PowerShell as administrator.', 'Run: powershell -ExecutionPolicy Bypass -File E:\\html\\NEXUS-L\\tools\\interlink-worker.ps1', 'Reload the Sync Center: the warning disappears.'], ['role_min' => 'admin', 'page_match' => 'interlink', 'diagnose' => 'worker']),

            // ------------------------------------------------------------------ problems and errors
            $k('The page is blank or white', 'blank page, white page, empty page, nothing shows, page not loading, white screen, page empty', 'Reload with Ctrl + F5. If it stays blank, you may have been signed out (the sign-in page should appear), or the server is busy. Wait a minute and reload. If it persists, tell an administrator which page it was.', ['Press Ctrl + F5.', 'Wait one minute and reload.', 'Press "Talk to an administrator" if it stays blank.']),
            $k('The system is slow or hangs', 'slow, hangs, hanging, lag, laggy, freezing, takes forever, loading forever, not responding, stuck loading, delay', 'Most pages load in under a second. If a page hangs for a long time, the server disk may be busy or stalled. Wait a minute and try again; do not press buttons repeatedly. Tell an administrator if it happens often, with the time it happened.', ['Wait up to one minute.', 'Reload with Ctrl + F5.', 'Report the time and the page to an administrator.'], ['diagnose' => 'disk']),
            $k('A button does nothing when I press it', 'button not working, button does nothing, click nothing, not responding button, nothing happens, no reaction, cannot click', 'Reload with Ctrl + F5 (an old copy of the page may be loaded) and try again. If a loading panel is showing, wait for it to finish. If still nothing, note the button name and tell an administrator; the assistant has also recorded the problem.', ['Press Ctrl + F5.', 'Wait for any loading panel to finish.', 'Try the button again.']),
            $k('I get a server error (500) or "Something went wrong"', 'server error, 500, internal server error, something went wrong, error page, exception, fatal error', 'A server error means the request failed on the server. Try again once. If it repeats, send the exact message and what you pressed to an administrator; the details are in the server log.', ['Try the action again once.', 'Press "Talk to an administrator" and describe what you pressed.'], ['error_match' => '500']),
            $k('Page not found (404)', 'not found, 404, page missing, broken link, wrong address, url not found', 'The address does not exist. Use the sidebar to open the page instead of an old bookmark. If you followed a link inside NEXUS-L and still got 404, tell an administrator.', [], ['error_match' => '404']),
            $k('Network error or cannot connect to the server', 'network error, cannot connect, connection lost, offline, server unreachable, failed to fetch, no connection, err_connection', 'Your computer cannot reach the NEXUS-L server. Check the network cable or Wi-Fi, then reload. If other websites work, the server may be restarting: wait a minute.', ['Check your network connection.', 'Wait a minute and reload.', 'Tell an administrator if it continues.'], ['error_match' => 'network']),
            $k('Why did my changes disappear?', 'changes lost, lost data, disappeared, work lost, unsaved, data gone, did not keep', 'Changes are only kept after you press Save. If you were signed out (30 minutes idle), reloaded the page, or the browser crashed, unsaved changes are gone. Reopen the report from the Lab Tracker to see what was last saved.', ['Open the report from the Lab Tracker.', 'Re-enter what is missing and press Save.']),
            $k('I see a duplicate record', 'duplicate, double record, same report twice, repeated, two records, copy', 'Save only once and wait for the confirmation. If two records exist for the same Lab Ref No., tell an administrator which one is correct; records are not deleted from the screen.'),
            $k('How do I report a problem or ask an administrator?', 'report problem, contact admin, talk to administrator, support, bug, ask admin, escalate, need human, help from admin', 'Press "Talk to an administrator" in this chat. The conversation (with what you did just before) goes to an administrator, who replies here. You do not have to explain from the beginning.'),
            $k('What does the system record about my activity?', 'privacy, tracking, record activity, terms, data collected, monitor, what is recorded, my history, who sees', 'To give better help, NEXUS-L records which pages you open, which buttons you press, and errors that happen. It never records passwords or what you type into fields. You can see your own recent activity (My history in this chat). Administrators see summaries to fix problems. This is part of the Terms and Privacy notice you accepted when registering.'),
            $k('How does the Inbox work?', 'inbox, chat, message colleague, send message, attachments, group chat, messaging, secure messaging', 'Open Inbox, pick a person (or press + for a new chat or group), type a message and press send. You can attach files, react to messages and pin chats. The unread count shows on the Inbox icon.', [], ['page_match' => 'inbox', 'actions' => [$o('Open Inbox', 'inbox')]]),

            // ------------------------------------------------------------------ admin
            $k('How do I teach the assistant new answers?', 'teach bot, train bot, add knowledge, brain console, add answer, bot knowledge, learn, import knowledge, train assistant', 'Open the Brain console (sidebar > Brain). "Teach" adds an answer; "Unanswered" lists questions the bot could not answer: answer them once and it knows them forever. "Import" loads many answers at once (JSON lines, CSV or plain text). When you solve an escalated chat, tick "Save as knowledge" to add your answer.', ['Brain > Unanswered: answer the most frequent questions first.', 'Brain > Teach: add a title, keywords people would use, the answer and steps.', 'Brain > Import: paste many Q&A at once.'], ['role_min' => 'admin', 'page_match' => 'brain', 'actions' => [$o('Open Brain console', 'brain', true)]]),
            $k('Where does the assistant keep what it learns?', 'brain folder, back file, knowledge back, where stored, backup brain, c brain, d brain, memory location, restore brain', 'In the database first, then exported as .back files (JSON lines) to E:\\html\\Brain and mirrored to C:\\Brain every minute: events-DATE.back (activity and errors), chats-DATE.back (conversations) and knowledge.back (every version of every answer). Playbooks are also written as readable Markdown in the playbooks folder (Obsidian can open them). If the knowledge table is ever lost, "Restore" in the Brain console rebuilds it from knowledge.back.', [], ['role_min' => 'admin', 'page_match' => 'brain', 'diagnose' => 'brain']),
            $k('How do I check the health of the system?', 'health check, system health, status check, diagnose system, check server, deployment check, what to check', 'Brain console > Health shows: machine-file location, PDF engine, InterLink session, background worker, free disk space and the Brain folders, plus the server settings that affect speed (compression, session handler, production mode).', [], ['role_min' => 'admin', 'page_match' => 'brain', 'diagnose' => 'brain']),
            $k('Pages hang for a long time (administrator)', 'pages hang admin, server stalls, realpath timeout, maximum execution time, session lock, disk stall, d drive slow, apache hang', 'Long hangs have been caused by the D: disk stalling (the log shows "Maximum execution time exceeded"), because PHP sessions are stored in files on that disk and one stuck request locks the others. Fix: run chkdsk D: /scan, move the NEXUS-L folder and its sessions to the SSD (C:), and keep the Brain mirror on C:.', ['Run chkdsk D: /scan.', 'Move the project (or at least writable/session) to the SSD.', 'Check Brain > Health for disk space.'], ['role_min' => 'admin', 'diagnose' => 'disk']),
        ];
    }
}
